package main

import (
	"fmt"
	"os"
	"strings"
)

// vectors: salt|password|hash22 — generated by glibc crypt(3) ($1$ MD5-crypt),
// compiled with gcc -lcrypt (genmd52.c). These are the ground-truth reference.
//
// Edge cases covered:
//   - salt 3, 4, 8 chars; salt 11 chars truncated to 8 (abcdefghij == abcdefgh)
//   - empty password, 1, 8 (DES boundary), 9, 16 (block boundary), 17, 32 chars
//   - long password not truncated (MD5-crypt uses full password)
//   - case-sensitive passwords
var md5Vectors = []string{
	"abc|a|uAXS.Zj1ZDNcW9iX1TVH2/",
	"abcd|12345678|uKnE387Q00O0L2.0Cm18e/",
	"abcd|123456789|h/.Te6wpHJ2m/EsOKvQeo0",
	"abcd|123456789xyz|E1G6iVo8.6kwR..gbLYef/",
	"open-xiaoai|open-xiaoai|nLuyH2rHYhdlW4Oy4DiqV0",
	"abcd||CwbBDotm4UoKv5fATTtzT.",
	"abcd|x|SwRG.yy0q6pJ8rg/8TwLf.",
	"abcd|abcdefgh|85NMKZ3AwytwRPUonecge/",
	"abcd|abcdefghi|8n5qEqHnW264FAtQ..v511",
	"abcd|abcdefghijklmnop|0Vy7Uz6XXq2x3e/M.8NyF.",
	"abcd|abcdefghijklmnopq|YSCXMa0lgrbQ3Jb6v4jtt1",
	"abcd|0123456789abcdef0123456789abcdef0123|Al07nYwRJhwAP8b2yYCxv0",
	// 11-char salt truncated to 8: must equal the 8-char-salt result
	"abcdefghij|hello|rwnEbRiN0agqVgZBovWNQ/",
	"abcdefgh|hello|rwnEbRiN0agqVgZBovWNQ/",
	"salt1234|secret|GexpiwjB8qThXlxv/yIG6.",
	"salt1234|Secret|66pzcen6ffbnAY2UXcxy60",
	"salt1234|s3Cr3t!|bnY.xpFYbPLyn/2qlL7Ce1",
	"Zz9AbCde|pw|9pkalYKcjNM4vI/xfzf3K0",
	"Zz9AbCde|password123|f9luMhCIx3S5Y8lL6hnap0",
	"Zz9AbCde|A-very-long-password-for-testing-256|zu6pG0/9dzhyrDWiEv5U51",
}

func runMD5VectorCheck() int {
	failed := 0
	for _, v := range md5Vectors {
		parts := strings.SplitN(v, "|", 3)
		if len(parts) != 3 {
			fmt.Println("BAD VECTOR LINE:", v)
			failed++
			continue
		}
		salt, pwd, want := parts[0], parts[1], parts[2]
		got := md5CryptHash(pwd, salt)
		// glibc caps the stored salt at 8 chars even when the setting had
		// more (e.g. "$1$abcdefghij$" -> "$1$abcdefgh$").
		storedSalt := salt
		if len(storedSalt) > 8 {
			storedSalt = storedSalt[:8]
		}
		wantFull := "$1$" + storedSalt + "$" + want
		if got != wantFull {
			// Note: stored hash keeps the FULL salt string even when the digest
			// used only 8 chars. So the expected full string uses the original
			// (possibly >8) salt.
			fmt.Printf("FAIL salt=%q pwd=%q\n  want %s\n  got  %s\n", salt, pwd, wantFull, got)
			failed++
			continue
		}
		if !verifyMd5Crypt(wantFull, pwd) {
			fmt.Printf("FAIL verify salt=%q pwd=%q\n", salt, pwd)
			failed++
			continue
		}
	}
	// salt derivation sanity: passwd-style salt from a password, verify roundtrip
	s := md5CryptSalt("hello123")
	if len(s) != 8 {
		fmt.Println("FAIL md5CryptSalt length:", len(s))
		failed++
	}
	h := md5CryptHash("hello123", s)
	if !verifyMd5Crypt(h, "hello123") {
		fmt.Println("FAIL salt roundtrip:", h)
		failed++
	}
	// wrong password must not verify
	if verifyMd5Crypt(h, "hello124") {
		fmt.Println("FAIL wrong-password accepted")
		failed++
	}
	// non-$1$ shadow fields
	if verifyMd5Crypt("root:*:0:0", "x") {
		fmt.Println("FAIL non-md5 entry accepted")
		failed++
	}
	_ = os.Stdout
	fmt.Printf("md5-crypt vectors: %d checked, %d failed\n", len(md5Vectors), failed)
	return failed
}
